contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address caller, address newOwner) public {
        require(caller != address(0) && caller != address(this) && newOwner != address(0), "invalid params");

        address initialOwner = c.owner();

        // The test contract is the deployer and thus the initial owner.
        require(initialOwner == address(this), "unexpected initial owner");

        // Try the transfer as `caller`, a non-owner (guaranteed by caller != address(this)).
        // Since msg.sender is the test contract, the call is attempted by the test contract itself,
        // which is the owner. To test the non-owner rule, we use a low-level call from a different address.
        // But we are restricted to calls on c. We can change ownership first to `caller` and then try to transfer from a non-owner?
        // However, the constraint says every state-changing call on c must be its own top-level statement and no cheatcodes.
        // We can achieve the test by first transferring ownership to `caller` (as current owner test contract), then
        // attempting a transfer as the test contract (which is now not the owner) and checking it reverts.

        // Step 1: transfer ownership to `caller` (allowed because we are the owner).
        // But we need to ensure that this transfer succeeds and then test the non-owner revert.
        // However, to have a non-owner caller, we need the test contract to not be the owner.
        // After transferring ownership to caller, the test contract is not the owner, so a subsequent transfer
        // call from the test contract should revert.

        // But beware: we need to avoid changing state if caller is already owner? No, caller != address(this) and initial owner is this.
        // So transfer to caller is allowed.

        // Transfer ownership to caller (state-changing call, top-level).
        c.transferOwnership(caller);

        // Now the owner should be caller.
        address ownerAfterFirst = c.owner();
        require(ownerAfterFirst == caller, "first transfer failed");

        // Now attempt a transfer as the test contract (which is no longer the owner).
        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: a non-owner cannot transfer ownership, so the call must revert.
        // Also, the owner must remain unchanged (caller).
        address finalOwner = c.owner();

        // Assert the rule: the call reverted and ownership unchanged.
        assert(reverted && finalOwner == caller);
    }

    receive() external payable {}
}

